/* From Uiverse.io by anonithrax - Tags: switch, theme-switch, toggle switch */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  position: relative;
  display: inline-block;
  width: 60px;
  height: 34px;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  display: none;
}

/* The slider */
.__UIV_SCOPE__ .switch label {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #ccc;
  transition: .3s;
}

.__UIV_SCOPE__ .switch label::before {
  position: absolute;
  content: "";
  height: 30px;
  width: 30px;
  left: 2px;
  bottom: 2px;
  background-color: white;
  transition: .3s;
}

.__UIV_SCOPE__ .switch input:checked + label {
  background-color: #4c71f2;
}

.__UIV_SCOPE__ .switch input:checked + label::before {
  transform: translateX(26px);
}
